def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [[x if x not in (1, 9) else 0 for x in row] for row in grid]
    water = sum(row.count(1) for row in grid)
    # Water descends until it reaches the lowest zero cell available in its column.
    # It can move sideways around colored obstacles as it falls.
    for _ in range(water):
        seen = {(0, c) for c in range(w) if g[0][c] == 0}
        stack = list(seen)
        best = None
        while stack:
            r, c = stack.pop()
            if best is None or r > best[0] or (r == best[0] and c < best[1]):
                best = (r, c)
            if r + 1 < h:
                if g[r + 1][c] == 0 and (r + 1, c) not in seen:
                    seen.add((r + 1, c))
                    stack.append((r + 1, c))
                else:
                    for dc in (-1, 1):
                        cc = c + dc
                        if 0 <= cc < w and g[r][cc] == 0 and (r, cc) not in seen:
                            seen.add((r, cc))
                            stack.append((r, cc))
        if best:
            g[best[0]][best[1]] = 1
    return g
